edges = [('T1', 'T2'), ('T2', 'T3'), ('T3', 'T4'), ('T4', 'T5'), ('T2', 'T4')]
tasks = ['T1', 'T2', 'T3', 'T4', 'T5']
in_degree = {t: 0 for t in tasks}
adj = {t: [] for t in tasks}
for u, v in edges:
    adj[u].append(v)
    in_degree[v] += 1
queue = [t for t in tasks if in_degree[t] == 0]
visited = 0
while queue:
    u = queue.pop(0)
    visited += 1
    for v in adj[u]:
        in_degree[v] -= 1
        if in_degree[v] == 0:
            queue.append(v)
if visited == len(tasks):
    print("SOLUTION:(A)")
else:
