edges = [('1', '6'), ('2', '6'), ('3', '5'), ('2', '5')]
adj = {}
for u, v in edges:
    adj.setdefault(u, set()).add(v)
    adj.setdefault(v, set()).add(u)
color = {}
is_bip = True
for node in adj:
    if node not in color:
        color[node] = 0
        q = [node]
        while q and is_bip:
            curr = q.pop(0)
            for neighbor in adj[curr]:
                if neighbor not in color:
                    color[neighbor] = 1 - color[curr]
                    q.append(neighbor)
                elif color[neighbor] == color[curr]:
                    is_bip = False
                    break
if is_bip:
    print("SOLUTION:(A)")
else:
    print("SOLUTION:(B)")

